4	//! # michi-truncate
5	//!
6	//! UTF-8 char-boundary safe content truncation primitives for michi and AXI.
7	
8	/// Result of a truncation operation.
9	#[derive(Debug, Clone, PartialEq)]
10	#[non_exhaustive]
11	pub struct Truncated {
12	    /// The truncated (or original) content string.
13	    pub content: String,
14	    /// Original byte length of the input.
15	    pub original_len: usize,
16	    /// Whether truncation actually occurred.
17	    pub was_truncated: bool,
18	    /// The truncation signal text that was actually embedded in `content`,
19	    /// starting immediately after the kept characters (leading space stripped).
20	    /// `None` when not truncated or when `max_chars` was so small that no
21	    /// signal text fit.
22	    pub signal: Option<String>,
23	}
24	
25	/// Truncate `content` to at most `max_chars` Unicode scalar values, appending
26	/// an agent-readable suffix when truncation occurs.
27	///
28	/// The suffix pattern is `" ({n} chars truncated — use {hint})"`. Uses char
29	/// boundaries — never splits a Unicode scalar.
30	///
31	/// Returns the original string unchanged when `content.chars().count() <= max_chars`.
32	#[must_use]
33	pub fn truncate(content: &str, max_chars: usize, hint: &str) -> Truncated {
34	    // Byte length is always >= char count, so if it already fits within
35	    // max_chars the char count does too — skip the full UTF-8 scan.
36	    if content.len() <= max_chars {
37	        return Truncated {
38	            content: content.to_string(),
39	            original_len: content.len(),
40	            was_truncated: false,
41	            signal: None,
42	        };
43	    }
44	
45	    let char_count = content.chars().count();
46	    if char_count <= max_chars {
47	        return Truncated {
48	            content: content.to_string(),
49	            original_len: content.len(),
50	            was_truncated: false,
51	            signal: None,
52	        };
53	    }
54	
55	    let suffix = format!(" ({char_count} chars truncated — use {hint})");
56	    let suffix_chars = suffix.chars().count();
57	    let keep_chars = max_chars.saturating_sub(suffix_chars);
58	
59	    let byte_end = content.char_indices().nth(keep_chars).map_or(content.len(), |(i, _)| i);
60	
61	    let mut result = String::with_capacity(byte_end + suffix.len());
62	    result.push_str(&content[..byte_end]);
63	    result.push_str(&suffix);
64	
65	    // Hard-cap to max_chars via char boundaries in case the suffix alone
66	    // exceeds max_chars (e.g. very small max_chars or long hint string).
67	    if result.chars().count() > max_chars {
68	        let cap_byte = result.char_indices().nth(max_chars).map_or(result.len(), |(i, _)| i);
69	        result.truncate(cap_byte);
70	    }
71	
72	    // Recompute signal based on what's actually in content after hard-cap
73	    let signal = if result.len() > byte_end {
74	        let signal_text = &result[byte_end..];
75	        let trimmed = signal_text.trim_start();
76	        if trimmed.is_empty() {
77	            None
78	        } else {
79	            Some(trimmed.to_string())
80	        }
81	    } else {
82	        None
83	    };
84	
85	    Truncated { content: result, original_len: content.len(), was_truncated: true, signal }
86	}
87	
88	/// Truncate content for inline use (e.g. inside a TOON field).
89	///
90	/// Returns the final string directly.
91	#[must_use]
92	pub fn truncate_inline(content: &str, max_chars: usize, hint: &str) -> String {
93	    truncate(content, max_chars, hint).content
94	}
