175	#[cfg(feature = "serde")]
176	fn json_value_to_toon_value(v: Option<&serde_json::Value>) -> Value {
177	    match v {
178	        None | Some(serde_json::Value::Null) => Value::Null,
179	        Some(serde_json::Value::Bool(b)) => Value::Bool(*b),
180	        Some(serde_json::Value::Number(n)) => {
181	            if let Some(i) = n.as_i64() {
182	                Value::Int(i)
183	            } else if let Some(f) = n.as_f64() {
184	                Value::Float(f)
185	            } else {
186	                Value::Str(compact_str::CompactString::new(n.to_string()))
187	            }
188	        }
189	        Some(serde_json::Value::String(s)) => Value::Str(compact_str::CompactString::new(s)),
190	        Some(other) => Value::Str(compact_str::CompactString::new(other.to_string())),
191	    }
192	}
