17	/// A single named component with a value and optional health signal.
18	#[derive(Debug, Clone, PartialEq)]
19	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
20	pub struct StatusItem {
21	    /// Component key, e.g. `"index"`, `"cache"`.
