29	/// Content-first orientation response (AXI **P8**).
30	#[derive(Debug, Clone, PartialEq)]
31	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
32	#[non_exhaustive]
33	pub struct StatusResponse {
34	    /// The tool's name, shown as the first line.
35	    pub tool_name: String,
36	    /// One-line description, shown as the second line.
37	    pub description: String,
38	    /// Component statuses.
39	    pub items: Vec<StatusItem>,
40	    /// Optional contextual hints for the agent.
41	    pub hints: Vec<Hint>,
42	}
43	
44	impl StatusResponse {
45	    /// Create a status response.
46	    pub fn new(tool_name: impl Into<String>, description: impl Into<String>, items: Vec<StatusItem>) -> Self {
47	        Self { tool_name: tool_name.into(), description: description.into(), items, hints: Vec::new() }
48	    }
49	
50	    /// Attach contextual hints.
51	    #[must_use]
52	    pub fn with_hints(mut self, hints: Vec<Hint>) -> Self {
53	        self.hints = hints;
54	        self
55	    }
56	
57	    /// Render this status response as an agent-readable string.
58	    #[must_use]
59	    pub fn render(&self) -> String {
60	        let mut kv_items = Vec::with_capacity(self.items.len() + 2);
61	        kv_items.push(KvItem { key: "tool".to_string(), value: KvValue::Text(self.tool_name.clone()) });
62	        kv_items.push(KvItem { key: "description".to_string(), value: KvValue::Text(self.description.clone()) });
63	        for item in &self.items {
64	            let annotated = match &item.health {
65	                None | Some(Health::Ok) => item.value.clone(),
66	                Some(Health::Degraded(reason)) => annotate(&item.value, "DEGRADED", reason),
67	                Some(Health::Error(reason)) => annotate(&item.value, "ERROR", reason),
68	            };
69	            kv_items.push(KvItem { key: item.key.clone(), value: annotated });
70	        }
71	        crate::kv::render_kv(&kv_items, None, &self.hints)
72	    }
73	}
74	
75	fn annotate(value: &KvValue, label: &str, reason: &str) -> KvValue {
76	    let mut display = String::new();
77	    crate::kv::push_kv_value(&mut display, value);
78	    KvValue::Text(format!("{display}  [{label}: {reason}]"))
79	}
