55	/// The MCP `CallToolResult` shape: what a tool call returns to a client.
56	#[derive(Debug, Clone, PartialEq)]
57	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
58	#[cfg_attr(feature = "serde", serde(into = "CallToolResultWire", from = "CallToolResultWire"))]
59	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
60	#[non_exhaustive]
61	pub struct CallToolResult {
62	    /// Text content blocks.
63	    pub content: Vec<ContentBlock>,
64	    /// Whether this is a tool execution error.
65	    pub is_error: bool,
66	    /// Machine-readable JSON companion to the text in `content`. This is
67	    /// typically a richer, typed representation (e.g. `AgentResponse::render_json()`
68	    /// or `DomainError::render_json()`) — it is NOT a copy of `content[0].text`.
69	    pub structured_content: String,
70	}
71	
72	impl CallToolResult {
73	    /// Create a new CallToolResult.
74	    pub fn new(content: Vec<ContentBlock>, is_error: bool, structured_content: impl Into<String>) -> Self {
75	        Self { content, is_error, structured_content: structured_content.into() }
76	    }
77	}
78	
79	#[cfg(feature = "serde")]
80	#[derive(serde::Serialize, serde::Deserialize)]
81	#[serde(rename_all = "camelCase")]
82	struct CallToolResultWire {
83	    content: Vec<ContentBlock>,
84	    is_error: bool,
85	    structured_content: serde_json::Value,
86	}
87	
88	#[cfg(feature = "serde")]
89	impl From<CallToolResult> for CallToolResultWire {
90	    fn from(r: CallToolResult) -> Self {
91	        // structured_content is always produced by render_json() which emits valid JSON.
92	        // If parsing fails, preserve the raw value as a JSON string rather than silently
93	        // replacing it with null — bad JSON from render_json() is a bug, not an expected case.
94	        let structured_content = serde_json::from_str(&r.structured_content)
95	            .unwrap_or_else(|_| serde_json::Value::String(r.structured_content));
96	        Self { content: r.content, is_error: r.is_error, structured_content }
97	    }
98	}
99	
100	#[cfg(feature = "serde")]
101	impl From<CallToolResultWire> for CallToolResult {
102	    fn from(w: CallToolResultWire) -> Self {
103	        let structured_content = serde_json::to_string(&w.structured_content).unwrap_or_default();
104	        Self { content: w.content, is_error: w.is_error, structured_content }
105	    }
106	}
