5	/// A single key-value pair for [`render_kv`].
6	#[derive(Debug, Clone, PartialEq)]
7	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
8	pub struct KvItem {
9	    /// The field name.
10	    pub key: String,
