13	}
14	
15	/// A value in a key-value item.
16	#[derive(Debug, Clone, PartialEq)]
17	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
18	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
19	pub enum KvValue {
20	    /// UTF-8 text value.
21	    Text(String),
22	    /// Signed integer.
23	    Int(i64),
24	    /// Floating-point number, rendered with the given number of decimal places.
25	    Float(f64, u8),
26	    /// Boolean renders as `true` or `false`.
27	    Bool(bool),
28	    /// Elapsed time, rendered as fractional seconds with one decimal.
29	    Duration(Duration),
30	    /// Absent value, renders as `—` (em dash).
31	    Missing,
32	}
33	
34	pub(crate) fn push_kv_value(out: &mut String, value: &KvValue) {
35	    match value {
36	        KvValue::Text(s) => {
37	            // Strip \n and \r — they break the one-line-per-key KV format
38	            if s.contains('\n') || s.contains('\r') {
39	                for ch in s.chars() {
40	                    if ch != '\n' && ch != '\r' {
41	                        out.push(ch);
42	                    }
43	                }
44	            } else {
45	                out.push_str(s);
46	            }
47	        }
48	        KvValue::Int(n) => {
49	            let _ = write!(out, "{n}");
50	        }
51	        KvValue::Float(f, decimals) => {
52	            let _ = write!(out, "{f:.*}", *decimals as usize);
53	        }
54	        KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
55	        KvValue::Duration(d) => {
56	            let _ = write!(out, "{:.1}s", d.as_secs_f64());
57	        }
58	        KvValue::Missing => out.push('—'),
59	    }
60	}
61	
62	pub(crate) fn json_escape_str(out: &mut String, s: &str) {
63	    out.push('"');
64	    for ch in s.chars() {
65	        match ch {
66	            '"' => out.push_str("\\\""),
67	            '\\' => out.push_str("\\\\"),
68	            '\n' => out.push_str("\\n"),
69	            '\r' => out.push_str("\\r"),
70	            '\t' => out.push_str("\\t"),
71	            other if u32::from(other) < 0x20 => {
72	                let code = u32::from(other);
73	                out.push_str("\\u00");
74	                out.push(char::from_digit(code >> 4, 16).unwrap_or('0'));
75	                out.push(char::from_digit(code & 0xf, 16).unwrap_or('0'));
76	            }
77	            other => out.push(other),
78	        }
79	    }
80	    out.push('"');
81	}
82	
83	pub(crate) fn kv_value_to_json(out: &mut String, value: &KvValue) {
84	    match value {
85	        KvValue::Text(s) => json_escape_str(out, s),
86	        KvValue::Int(n) => {
87	            let _ = write!(out, "{n}");
88	        }
89	        KvValue::Float(f, decimals) => {
90	            if f.is_nan() || f.is_infinite() {
91	                // NaN and Infinity are not valid JSON numbers — render as quoted strings
92	                // to avoid producing invalid JSON output
93	                let s = format!("{f:.*}", *decimals as usize);
94	                json_escape_str(out, &s);
95	            } else {
96	                let _ = write!(out, "{f:.*}", *decimals as usize);
97	            }
98	        }
99	        KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
100	        KvValue::Duration(d) => {
101	            let mut secs = String::new();
102	            let _ = write!(secs, "{:.1}s", d.as_secs_f64());
103	            json_escape_str(out, &secs);
104	        }
105	        KvValue::Missing => out.push_str("null"),
106	    }
107	}
108	
109	/// Render a list of key-value pairs as a column-aligned multi-line block.
110	///
111	/// Key padding uses `chars().count()`, not display width. Keys containing
112	/// CJK or other wide Unicode characters will appear misaligned in monospace
113	/// terminals. This is acceptable: michi targets agent readability (where
114	/// display width is not relevant), not human terminal rendering.
115	#[must_use]
116	pub fn render_kv(items: &[KvItem], total_count: Option<usize>, hints: &[Hint]) -> String {
117	    if items.is_empty() {
118	        return String::new();
119	    }
120	    let max_key_len = items.iter().map(|i| i.key.chars().count()).max().unwrap_or(0);
121	    let capacity = items.len() * (max_key_len + 24) + hints.len() * 50 + 20;
122	    let mut out = String::with_capacity(capacity);
123	    for item in items {
124	        out.push_str(&item.key);
125	        out.push(':');
126	        let pad = max_key_len - item.key.chars().count() + 1;
127	        for _ in 0..pad {
128	            out.push(' ');
129	        }
130	        push_kv_value(&mut out, &item.value);
131	        out.push('\n');
132	    }
133	    if let Some(total) = total_count {
134	        out.push_str("totalCount: ");
135	        let _ = write!(out, "{total}");
136	        out.push('\n');
137	    }
138	    crate::hints::append_hints(&mut out, hints);
139	    out
140	}
