1	/// A single operation that failed within a larger multi-step operation.
2	#[derive(Debug, Clone, PartialEq)]
3	pub struct FailedOp {
4	    /// Identifier of the operation that failed.
5	    pub operation: String,
6	    /// Human-readable failure reason.
7	    pub reason: String,
8	    /// Optional structured recovery hint for this specific failure.
9	    pub recovery: Option<crate::recovery::RecoveryHint>,
10	}
11	
12	/// Signals that an operation partially completed before a failure.
13	///
14	/// Use this when some steps of a multi-step operation succeeded — the agent
15	/// can resume from the checkpoint rather than retrying from scratch.
16	///
17	/// For a fully-completed prior call, see [`michi_resilience::AlreadyDone`]
18	/// and [`michi_resilience::already_done`].
19	#[derive(Debug, Clone, PartialEq)]
20	pub struct PartialSuccess {
21	    /// Identifiers of steps that completed successfully.
22	    pub completed: Vec<String>,
23	    /// Steps that failed, with reason and optional recovery hint.
24	    pub failed: Vec<FailedOp>,
25	    /// Identifiers of steps that were not attempted.
26	    pub skipped: Vec<String>,
27	}
28	
29	impl PartialSuccess {
30	    /// Render as an agent-readable string: a summary line, one block per
31	    /// non-empty outcome category, then any per-op recovery hints folded into
32	    /// a trailing `help[]` block.
33	    ///
34	    /// Format:
35	    /// ```text
36	    /// partial_success: 2 completed, 1 failed, 1 skipped
37	    /// completed[2]:
38	    ///   create_issue
39	    ///   add_label
40	    /// failed[1]{operation,reason}:
41	    ///   assign_user,"User 'ghost' not found"
42	    /// skipped[1]:
43	    ///   notify_team
44	    /// help[1]:
45	    ///   assign_user: suggestedParams: { user: alice }
46	    /// ```
47	    ///
48	    /// Empty categories are omitted.
49	    #[must_use]
50	    pub fn render(&self) -> String {
51	        let mut out = String::with_capacity(
52	            64 + self.completed.iter().map(String::len).sum::<usize>()
53	                + self.failed.iter().map(|f| f.operation.len() + f.reason.len() + 60).sum::<usize>()
54	                + self.skipped.iter().map(String::len).sum::<usize>(),
55	        );
56	        out.push_str("partial_success: ");
57	        out.push_str(&self.completed.len().to_string());
58	        out.push_str(" completed, ");
59	        out.push_str(&self.failed.len().to_string());
60	        out.push_str(" failed, ");
61	        out.push_str(&self.skipped.len().to_string());
62	        out.push_str(" skipped\n");
63	
64	        if !self.completed.is_empty() {
65	            out.push_str("completed[");
66	            out.push_str(&self.completed.len().to_string());
67	            out.push_str("]:\n");
68	            for op in &self.completed {
69	                out.push_str("  ");
70	                out.push_str(op);
71	                out.push('\n');
72	            }
73	        }
74	
75	        if !self.failed.is_empty() {
76	            out.push_str("failed[");
77	            out.push_str(&self.failed.len().to_string());
78	            out.push_str("]{operation,reason}:\n");
79	            for f in &self.failed {
80	                out.push_str("  ");
81	                // operation: conditionally quoted (only when it contains commas/quotes/newlines)
82	                out.push_str(michi_toon::escape_value(&f.operation).as_ref());
83	                out.push(',');
84	                // reason: always quoted — it is human-readable prose and often contains quotes
85	                out.push_str(&michi_toon::escape_value_quoted(&f.reason));
86	                out.push('\n');
87	            }
88	        }
89	
90	        if !self.skipped.is_empty() {
91	            out.push_str("skipped[");
92	            out.push_str(&self.skipped.len().to_string());
93	            out.push_str("]:\n");
94	            for op in &self.skipped {
95	                out.push_str("  ");
96	                out.push_str(op);
97	                out.push('\n');
98	            }
99	        }
100	
101	        let recovery_hints: Vec<crate::recovery::RecoveryHint> =
102	            self.failed.iter().filter_map(|f| f.recovery.clone()).collect();
103	        if !recovery_hints.is_empty() {
104	            out.push_str("help[");
105	            out.push_str(&recovery_hints.len().to_string());
106	            out.push_str("]:\n");
107	            // Use inner append_recovery_lines (pub(crate)) to avoid the `recovery[N]:` header
108	            // that append_recovery would write — the section header here is `help[N]:`.
109	            crate::recovery::append_recovery_lines(&mut out, &recovery_hints);
110	        }
111	
112	        out
113	    }
114	
115	    /// `0` when all operations completed or were skipped; `1` when any failed.
116	    #[must_use]
117	    pub fn exit_code(&self) -> i32 {
118	        i32::from(!self.failed.is_empty())
119	    }
120	}
121	
