<title>Callisto</title>
<style>
  :root {
    --bg: #F6F7F9;
    --surface: #FFFFFF;
    --surface-2: #EEF1F4;
    --ink: #161B22;
    --ink-muted: #5B6572;
    --ink-faint: #8992A0;
    --line: #DFE3E8;
    --accent: #146A96;
    --accent-soft: #DCEEF6;
    --amber: #9A6413;
    --amber-soft: #F7EBD6;
    --good: #1E7A50;
    --good-soft: #DFF1E7;
    --mono: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono", Consolas, monospace;
    --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #0E1217;
      --surface: #151A21;
      --surface-2: #1B222B;
      --ink: #E7EAEE;
      --ink-muted: #98A2AF;
      --ink-faint: #626D7A;
      --line: #262E38;
      --accent: #6BC0EC;
      --accent-soft: #16303C;
      --amber: #E3B15E;
      --amber-soft: #362A16;
      --good: #7ED4A8;
      --good-soft: #163427;
    }
  }

  :root[data-theme="dark"] {
    --bg: #0E1217;
    --surface: #151A21;
    --surface-2: #1B222B;
    --ink: #E7EAEE;
    --ink-muted: #98A2AF;
    --ink-faint: #626D7A;
    --line: #262E38;
    --accent: #6BC0EC;
    --accent-soft: #16303C;
    --amber: #E3B15E;
    --amber-soft: #362A16;
    --good: #7ED4A8;
    --good-soft: #163427;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: var(--serif);
    font-size: 17px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  ::selection { background: var(--accent-soft); }

  .page {
    max-width: 780px;
    margin: 0 auto;
    padding: 64px 28px 96px;
  }

  .eyebrow {
    font-family: var(--mono);
    font-size: 12px;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--ink-faint);
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .eyebrow .dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--good);
    box-shadow: 0 0 0 3px var(--good-soft);
    flex: none;
  }

  header.hero {
    margin-bottom: 52px;
  }

  h1 {
