    "Append inside `mod tests`:

    /// Splits one TOON data row ("  field,field,field\n" without its leading
    /// two-space indent) into its comma-separated fields, respecting the
    /// quoted-field grammar from docs/spec/02-toon-format.md: a field
    /// beginning with `"` runs until its closing unescaped `"`, treating
    /// `\"` as an escaped quote; commas inside a quoted field are not field
    /// separators.
    fn split_toon_row(row: &str) -> Vec<String> {
        let mut fields = Vec::new();
        let mut chars = row.chars().peekable();
        while chars.peek().is_some() {
            let mut field = String::new();
            if chars.peek() == Some(&'"') {
                chars.next();
                while let Some(c) = chars.next() {
                    if c == '\\' {
                        if let Some(escaped) = chars.next() {
                            field.push(escaped);
                        }
                    } else if c == '"' {
                        break;
                    } else {
                        field.push(c);
                    }
                }
            } else {
                while let Some(&c) = chars.peek() {
                    if c == ',' {
                        break;
                    }
                    field.push(c);
                    chars.next();
                }
            }
            fields.push(field);
            if chars.peek() == Some(&',') {
                chars.next();
            }
        }
        fields
    }

