{
  "id": "T12-multi-dependency-accumulation-behavior",
  "title": "Prove B waits for both A1 and A2, and that A1's failure alone skips B without ever invoking B before A2 resolves",
  "depends_on": [
    "T11-dependency-respecting-execution"
  ],
  "covers_criteria": [
    "AC-004"
  ],
  "files": {
    "modify": [
      "crates/michi-pipeline/src/lib.rs"
    ]
  },
  "steps": [
    "Note (no implementation change in this task): CircuitBreaker::call wraps every attempt in its own per-attempt tokio::time::timeout (see the breaker's step_timeout handling), so a step whose future never resolves on its own (e.g. a NeverResolves-style runner) still returns Err(Timeout) once its own step_timeout elapses - execute_pipeline_parallel's plain `while let Some(joined) = join_set.join_next().await` loop from T09b already terminates in that case with no special-casing. T09b's loop is therefore left completely unchanged by this task; there is no rewrite to make here.",
    "RED - Append inside `mod tests`:

    #[tokio::test(start_paused = true)]
    async fn dependent_waits_for_both_declared_prerequisites_to_complete() {
        let mut pipeline = make_pipeline(&["a1", "a2", "b"]);
        let ids = vec!["a1".to_string(), "a2".to_string(), "b".to_string()];
        let mut deps = StepDependencies::new(&ids).unwrap();
        deps.depends_on("b", "a1");
        deps.depends_on("b", "a2");
        let breaker = std::sync::Arc::new(CircuitBreaker::new(
            michi_resilience::RetryConfig::default(),
            Duration::from_secs(5),
            1,
            Duration::from_secs(60),
        ));
        let runners: Vec<Box<dyn Step>> = (0..3)
            .map(|_| Box::new(CountingStep { calls: std::sync::atomic::AtomicU32::new(0) }) as Box<dyn Step>)
            .collect();
        let result = execute_pipeline_parallel(&mut pipeline, &deps, runners, breaker, 0.0).await;
        assert!(result.is_ok());
        for step in &pipeline.steps {
            assert_eq!(step.status, michi_core::pipeline::StepStatus::Completed);
        }
    }

    struct GatedNeverResolves(std::sync::Arc<tokio::sync::Notify>);
    impl Step for GatedNeverResolves {
        fn run<'a>(&'a self, _attempt: u32) -> Pin<Box<dyn Future<Output = Result<(), ExecutionError>> + Send + 'a>> {
            let notify = std::sync::Arc::clone(&self.0);
            Box::pin(async move {
                notify.notified().await;
                Ok(())
            })
        }
    }

    struct CountingSkippableStep(std::sync::Arc<std::sync::atomic::AtomicU32>);
    impl Step for CountingSkippableStep {
        fn run<'a>(&'a self, _attempt: u32) -> Pin<Box<dyn Future<Output = Result<(), ExecutionError>> + Send + 'a>> {
            self.0.fetch_add(1, Ordering::SeqCst);
            Box::pin(async { Ok(()) })
        }
    }

    #[tokio::test(start_paused = true)]
    async fn dependent_is_skipped_as_soon_as_either_prerequisite_fails_without_waiting_for_the_other() {
        let mut pipeline = make_pipeline(&["a1", "a2", "b"]);
        let ids = vec!["a1".to_string(), "a2".to_string(), "b".to_string()];
        let mut deps = StepDependencies::new(&ids).unwrap();
        deps.depends_on("b", "a1");
        deps.depends_on("b", "a2");
        let breaker = std::sync::Arc::new(CircuitBreaker::new(
            michi_resilience::RetryConfig::new(0, Duration::from_millis(1), Duration::from_secs(1), 0.0),
            Duration::from_secs(3600),
            u32::MAX,
            Duration::from_secs(60),
        ));
        let a2_notify = std::sync::Arc::new(tokio::sync::Notify::new());
        let b_calls = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let runners: Vec<Box<dyn Step>> = vec![
            Box::new(AlwaysFailStep { retryable: false, calls: std::sync::atomic::AtomicU32::new(0) }),
            Box::new(GatedNeverResolves(std::sync::Arc::clone(&a2_notify))),
            Box::new(CountingSkippableStep(std::sync::Arc::clone(&b_calls))),
        ];

        let result = {
            let fut = execute_pipeline_parallel(&mut pipeline, &deps, runners, breaker, 0.0);
            tokio::pin!(fut);
            let waker = std::task::Waker::noop();
            let mut cx = std::task::Context::from_waker(waker);

            // Manually poll the still-pending future a bounded number of times,
            // cooperatively yielding the underlying tasks between polls, without
            // ever notifying a2 or advancing virtual time past its wait. This
            // gives a1's immediate failure and skip-propagation to b every
            // chance to happen while a2 (and therefore the whole run) is
            // provably still not resolved.
            for _ in 0..8 {
                let poll = fut.as_mut().poll(&mut cx);
                assert!(matches!(poll, std::task::Poll::Pending), "the run must not resolve before a2 is notified");
                tokio::task::yield_now().await;
            }
            assert_eq!(b_calls.load(Ordering::SeqCst), 0, "b must not be invoked while a1 has failed but a2 has not yet been released - this is the witness that b's skip does not wait on a2");

            // a2 is released, and `fut` is awaited to completion, still
            // inside this block - so the pinned future (and its hidden
            // local holding `&mut pipeline`) is fully dropped by the time
            // this block ends, before any `pipeline.steps[..]` access below.
            a2_notify.notify_one();
            fut.await
