    struct DelayedPanicStep;
    impl Step for DelayedPanicStep {
        fn run<'a>(&'a self, _attempt: u32) -> Pin<Box<dyn Future<Output = Result<(), ExecutionError>> + Send + 'a>> {
            Box::pin(async {
                // The delay guarantees b's result is drained by join_next()
