        "int" => michi_toon::Value::Int(v.int_val.map_or(0, JsInt::get)),
        "float" => michi_toon::Value::Float(v.float_val.map_or(0.0, JsFloat::get)),
        "bool" => michi_toon::Value::Bool(v.bool_val.unwrap_or(false)),
        _ => michi_toon::Value::Null,
