#[test]
fn sole_constructor_for_toon_document() {
    // Strips every `#[cfg(test)] mod ... { ... }` block from `src` via
    // brace matching, not a first-occurrence prefix split -- a prefix
    // split silently stops scanning at the first test module even if
    // real (non-test) code follows it later in the file.
    fn strip_test_modules(src: &str) -> String {
        let mut out = String::with_capacity(src.len());
        let mut rest = src;
        while let Some(marker_idx) = rest.find("#[cfg(test)]") {
            out.push_str(&rest[..marker_idx]);
            let after_marker = &rest[marker_idx..];
            let brace_start =
                after_marker.find('{').expect("#[cfg(test)] attribute must be followed by a module body");
            let mut depth = 0i32;
            let mut end = None;
            for (i, c) in after_marker[brace_start..].char_indices() {
                match c {
                    '{' => depth += 1,
                    '}' => {
                        depth -= 1;
                        if depth == 0 {
                            end = Some(brace_start + i + 1);
                            break;
                        }
                    }
                    _ => {}
                }
            }
            rest = &after_marker[end.expect("unbalanced braces in #[cfg(test)] module")..];
        }
        out.push_str(rest);
        out
    }

    // Extracts the body of `impl<'a> ToonDocument<'a> { ... }` via brace
    // matching.
    fn extract_toon_document_impl_block(src: &str) -> &str {
        let marker = "impl<'a> ToonDocument<'a> {";
        let start = src.find(marker).expect("ToonDocument's impl block must exist in render.rs");
        let brace_start = start + marker.len() - 1;
        let mut depth = 0i32;
        let mut end = None;
        for (i, c) in src[brace_start..].char_indices() {
            match c {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        end = Some(brace_start + i + 1);
                        break;
                    }
                }
                _ => {}
            }
        }
        let end = end.expect("unbalanced braces in ToonDocument's impl block");
        &src[brace_start + 1..end - 1]
    }

    let render_src = strip_test_modules(include_str!("render.rs"));
    let lib_src = strip_test_modules(include_str!("lib.rs"));
    let escape_src = strip_test_modules(include_str!("escape.rs"));

    // The impl block that owns ToonDocument's private field must contain
    // exactly one associated function (a `fn` whose first parameter is
    // not `self`/`&self`/`&mut self`): `validate`. Counting associated
    // functions structurally -- rather than matching a specific return
    // type substring -- catches a bypass constructor regardless of what
    // it returns or is named, e.g. a `pub(crate) fn wrap(...) -> Self`
    // that a substring match on `-> Result<Self, crate::ToonError>` or
    // `-> ToonDocument` would silently miss.
    let impl_block = extract_toon_document_impl_block(&render_src);
    let associated_fns = impl_block
        .split("fn ")
        .skip(1)
        .filter(|rest| {
            let params = rest.split_once('(').map_or("", |(_, p)| p).trim_start();
            !(params.starts_with("self") || params.starts_with("&self") || params.starts_with("&mut self"))
        })
        .count();
    assert_eq!(
        associated_fns, 1,
        "ToonDocument's impl block must contain exactly one associated function (validate); found {associated_fns}"
    );

    for (file, src) in [("render.rs", render_src.as_str()), ("lib.rs", lib_src.as_str()), ("escape.rs", escape_src.as_str())]
    {
        let scan = src.to_lowercase().replace("unsafe_code", "");
        for bad in ["unchecked", "unsafe", "raw", "assume"] {
            assert!(!scan.contains(bad), "escape-hatch name pattern {bad:?} must not appear in {file}");
        }
    }
}

