#[test]
fn sole_constructor_for_toon_document() {
    // Finds the byte offset one past the `}` that closes the brace
    // opened at `open_brace_idx`, skipping brace characters that occur
    // inside `"..."` string literals (this file's test bodies render
    // TOON output containing literal `{`/`}`, which would otherwise
    // desynchronize a naive depth counter) and `'.'` char literals.
    fn find_matching_close_brace(s: &str, open_brace_idx: usize) -> Option<usize> {
        let mut depth = 0i32;
        let mut in_string = false;
        let mut escaped = false;
        for (i, c) in s[open_brace_idx..].char_indices() {
            if escaped {
                escaped = false;
                continue;
            }
            match c {
                '\\' if in_string => escaped = true,
                '"' => in_string = !in_string,
                '{' if !in_string => depth += 1,
                '}' if !in_string => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(open_brace_idx + i + 1);
                    }
                }
                _ => {}
            }
        }
        None
    }

    // Strips every `#[cfg(test)] mod ... { ... }` block from `src` via
    // brace matching, not a first-occurrence prefix split -- a prefix
    // split silently stops scanning at the first test module even if
    // real (non-test) code follows it later in the file.
    fn strip_test_modules(src: &str) -> String {
