// Finds the byte offset one past the `}` that closes the brace
// opened at `open_brace_idx`, skipping brace characters that occur
// inside `"..."` string literals or `'{'`/`'}'` char literals (this
// file's test bodies render TOON output containing literal `{`/`}`
// in both forms, which would otherwise desynchronize a naive depth
// counter). A bare `'` that isn't immediately followed by `x'` or
// `\x'` is a lifetime, not a char literal, and is left alone.
fn find_matching_close_brace(s: &str, open_brace_idx: usize) -> Option<usize> {
    let chars: Vec<(usize, char)> = s[open_brace_idx..].char_indices().collect();
    let mut depth = 0i32;
    let mut in_string = false;
    let mut i = 0usize;
    while i < chars.len() {
        let (byte_idx, c) = chars[i];
        if !in_string && c == '\'' {
            let is_escaped_char_lit = chars.get(i + 1).is_some_and(|&(_, c)| c == '\\')
                && chars.get(i + 3).is_some_and(|&(_, c)| c == '\'');
            let is_plain_char_lit = chars.get(i + 2).is_some_and(|&(_, c)| c == '\'');
            if is_escaped_char_lit {
                i += 4;
                continue;
            } else if is_plain_char_lit {
                i += 3;
                continue;
            }
            i += 1;
            continue;
        }
        if c == '\\' && in_string {
            i += 2;
            continue;
        }
        match c {
            '"' => in_string = !in_string,
            '{' if !in_string => depth += 1,
            '}' if !in_string => {
                depth -= 1;
                if depth == 0 {
                    return Some(open_brace_idx + byte_idx + 1);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

