// in both forms, which would otherwise desynchronize a naive depth
// counter). Only these two specific char literals are special-cased
// -- a bare `'` elsewhere (a lifetime, or an apostrophe in a doc
// comment) contains no brace character, so it cannot desync the
// counter and is deliberately left unrecognized as anything special.
fn find_matching_close_brace(s: &str, open_brace_idx: usize) -> Option<usize> {
    let chars: Vec<(usize, char)> = s[open_brace_idx..].char_indices().collect();
    let mut depth = 0i32;
    let mut in_string = false;
    let mut i = 0usize;
    while i < chars.len() {
        let (byte_idx, c) = chars[i];
        if !in_string
            && c == '\''
            && matches!(chars.get(i + 1), Some(&(_, '{' | '}')))
            && matches!(chars.get(i + 2), Some(&(_, '\'')))
        {
            i += 3;
            continue;
        }
        if c == '\\' && in_string {
            i += 2;
            continue;
        }
        match c {
            '"' => in_string = !in_string,
            '{' if !in_string => depth += 1,
            '}' if !in_string => {
                depth -= 1;
                if depth == 0 {
                    return Some(open_brace_idx + byte_idx + 1);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

