// Finds the byte offset one past the `}` that closes the brace
// opened at `open_brace_idx`, skipping brace characters that occur
// inside `"..."` string literals, `'{'`/`'}'` char literals, or a
// `'\u{XXXX}'` Unicode-escape char literal (this file's test bodies
// render TOON output containing literal `{`/`}` in all three forms,
// which would otherwise desynchronize a naive depth counter). A bare
// `'` elsewhere (a lifetime, or an apostrophe in a doc comment)
// contains no brace character, so it cannot desync the counter and
// is deliberately left unrecognized as anything special.
fn find_matching_close_brace(s: &str, open_brace_idx: usize) -> Option<usize> {
    let chars: Vec<(usize, char)> = s[open_brace_idx..].char_indices().collect();
    let mut depth = 0i32;
    let mut in_string = false;
    let mut i = 0usize;
    while i < chars.len() {
        let (byte_idx, c) = chars[i];
        if !in_string && c == '\'' {
            let is_brace_char_lit = matches!(chars.get(i + 1), Some(&(_, '{' | '}')))
                && matches!(chars.get(i + 2), Some(&(_, '\'')));
            let is_unicode_escape_lit = matches!(chars.get(i + 1), Some(&(_, '\\')))
                && matches!(chars.get(i + 2), Some(&(_, 'u')))
                && matches!(chars.get(i + 3), Some(&(_, '{')));
            if is_brace_char_lit {
                i += 3;
                continue;
            } else if is_unicode_escape_lit {
                let close = chars[i + 4..]
                    .iter()
                    .position(|&(_, c)| c == '}')
                    .expect("unclosed \\u{ escape in char literal");
                i += 4 + close + 2; // + '}' + closing quote
                continue;
            }
        }
        if c == '\\' && in_string {
            i += 2;
            continue;
        }
        match c {
            '"' => in_string = !in_string,
            '{' if !in_string => depth += 1,
            '}' if !in_string => {
                depth -= 1;
                if depth == 0 {
                    return Some(open_brace_idx + byte_idx + 1);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

// Strips every `#[cfg(test)] mod ... { ... }` block from `src` via
// brace matching, not a first-occurrence prefix split -- a prefix
// split silently stops scanning at the first test module even if
// real (non-test) code follows it later in the file.
fn strip_test_modules(src: &str) -> String {
    let mut out = String::with_capacity(src.len());
    let mut rest = src;
    while let Some(marker_idx) = rest.find("#[cfg(test)]") {
        out.push_str(&rest[..marker_idx]);
        let after_marker = &rest[marker_idx..];
        let brace_start =
            after_marker.find('{').expect("#[cfg(test)] attribute must be followed by a module body");
        let end = find_matching_close_brace(after_marker, brace_start)
            .expect("unbalanced braces in #[cfg(test)] module");
        rest = &after_marker[end..];
    }
    out.push_str(rest);
    out
}

// Extracts the body of `impl<'a> ToonDocument<'a> { ... }` via brace
// matching.
fn extract_toon_document_impl_block(src: &str) -> &str {
    let marker = "impl<'a> ToonDocument<'a> {";
    let start = src.find(marker).expect("ToonDocument's impl block must exist in render.rs");
    let brace_start = start + marker.len() - 1;
    let end = find_matching_close_brace(src, brace_start)
        .expect("unbalanced braces in ToonDocument's impl block");
    &src[brace_start + 1..end - 1]
}

