101	    /// Classifies whether retrying is worthwhile for this error.
102	    #[must_use]
103	    pub fn is_retryable(&self) -> bool {
104	        match self {
105	            Self::Http { status, .. } => michi_resilience::is_retryable_status(*status),
106	            Self::Timeout { .. } => true,
107	            Self::Failed { retryable, .. } => *retryable,
108	            Self::CircuitOpen { .. } => true,
109	            Self::StepFailed { source, .. } => source.is_retryable(),
110	            Self::StepCountMismatch { .. } => false,
111	            Self::UnknownStepId { .. } => false,
112	            Self::DuplicateStepId { .. } => false,
113	            Self::CyclicDependency { .. } => false,
114	            Self::Cancelled => false,
115	        }
116	    }
117	}
