119	/// Extracts the caller-supplied retry hint from an error, recursing through
120	/// [`ExecutionError::StepFailed`] into its wrapped `source` so a step
121	/// failure never discards an inner `Http`/`CircuitOpen` retry hint.
122	fn retry_after_for(err: &ExecutionError) -> Option<Duration> {
123	    match err {
124	        ExecutionError::Http { retry_after, .. } => *retry_after,
125	        ExecutionError::CircuitOpen { retry_after_ms } => Some(Duration::from_millis(*retry_after_ms)),
126	        ExecutionError::StepFailed { source, .. } => retry_after_for(source),
127	        ExecutionError::Timeout { .. }
128	        | ExecutionError::Failed { .. }
129	        | ExecutionError::StepCountMismatch { .. }
130	        | ExecutionError::UnknownStepId { .. }
131	        | ExecutionError::DuplicateStepId { .. }
132	        | ExecutionError::CyclicDependency { .. }
133	        | ExecutionError::Cancelled => None,
134	    }
