209	impl From<ExecutionError> for michi_core::DomainError {
210	    fn from(err: ExecutionError) -> Self {
211	        match err {
212	            ExecutionError::Http { status, message, retry_after } => {
213	                let code = match status {
214	                    429 => michi_core::ErrorCode::RateLimited,
215	                    502..=504 => michi_core::ErrorCode::Unavailable,
216	                    _ => michi_core::ErrorCode::ExternalFailure,
217	                };
218	                let retryable = michi_resilience::is_retryable_status(status);
219	                let mut domain_err = michi_core::DomainError::new(code, message).retryable(retryable);
220	                if let Some(retry_after) = retry_after {
221	                    domain_err = domain_err.retry_after(retry_after);
222	                }
223	                domain_err
224	            }
225	            ExecutionError::Timeout { elapsed_ms } => michi_core::DomainError::new(
226	                michi_core::ErrorCode::Timeout,
227	                format!("step timed out after {elapsed_ms}ms"),
228	            )
229	            .retryable(true),
230	            ExecutionError::Failed { message, retryable } => {
231	                michi_core::DomainError::new(michi_core::ErrorCode::ExternalFailure, message).retryable(retryable)
232	            }
233	            ExecutionError::CircuitOpen { retry_after_ms } => michi_core::DomainError::new(
234	                michi_core::ErrorCode::Unavailable,
235	                format!("circuit open, retry after {retry_after_ms}ms"),
236	            )
237	            .retryable(true)
238	            .retry_after(std::time::Duration::from_millis(retry_after_ms)),
239	            ExecutionError::StepFailed { step_id, step_name, source } => {
240	                let inner: michi_core::DomainError = (*source).into();
241	                let message = format!("step {step_id} ({step_name}) failed: {}", inner.message);
242	                let mut domain_err = michi_core::DomainError::new(inner.code, message).retryable(inner.retryable);
243	                if let Some(retry_after) = inner.retry_after {
244	                    domain_err = domain_err.retry_after(retry_after);
245	                }
246	                domain_err
247	            }
248	            ExecutionError::StepCountMismatch { expected, got } => michi_core::DomainError::new(
249	                michi_core::ErrorCode::InvalidInput,
250	                format!("expected {expected} runners, got {got}"),
251	            )
252	            .retryable(false),
253	            ExecutionError::UnknownStepId { step_id } => {
254	                michi_core::DomainError::new(michi_core::ErrorCode::InvalidInput, format!("unknown step id: {step_id}"))
255	                    .retryable(false)
256	            }
257	            ExecutionError::DuplicateStepId { step_id } => michi_core::DomainError::new(
258	                michi_core::ErrorCode::InvalidInput,
259	                format!("duplicate step id: {step_id}"),
260	            )
261	            .retryable(false),
262	            ExecutionError::CyclicDependency { step_id } => michi_core::DomainError::new(
263	                michi_core::ErrorCode::InvalidInput,
264	                format!("cyclic dependency involving step id: {step_id}"),
265	            )
266	            .retryable(false),
267	            ExecutionError::Cancelled => {
268	                michi_core::DomainError::new(michi_core::ErrorCode::Unavailable, "pipeline execution cancelled")
269	                    .retryable(false)
270	            }
271	        }
272	    }
273	}
