289	impl StepDependencies {
290	    /// Constructs an empty dependency graph (no edges) over ids. Fails
291	    /// with ExecutionError::DuplicateStepId if ids contains the same
292	    /// id more than once.
293	    pub fn new(ids: &[String]) -> Result<Self, ExecutionError> {
294	        let mut seen = HashSet::new();
295	        for id in ids {
296	            if !seen.insert(id.clone()) {
297	                return Err(ExecutionError::DuplicateStepId { step_id: id.clone() });
298	            }
299	        }
300	        #[allow(clippy::disallowed_types, reason = "internal adjacency map, never rendered as output")]
301	        let edges = HashMap::new();
302	        Ok(Self { ids: seen, edges })
303	    }
