305	    /// Declares that dependent must not be invoked until dependency has
306	    /// reached StepStatus::Completed. Calling this repeatedly for the same
307	    /// dependent accumulates additional prerequisite edges rather than
308	    /// overwriting prior ones.
309	    pub fn depends_on(&mut self, dependent: &str, dependency: &str) {
310	        self.edges.entry(dependent.to_string()).or_default().push(dependency.to_string());
