314	/// Returns Some(step_id) for one step id participating in a cycle formed
315	/// by deps's edges (including a 1-node self-dependency), or None if the
316	/// graph is acyclic. Uses a standard 3-color DFS: White (unvisited), Gray
317	/// (on the current recursion stack), Black (fully explored).
318	#[allow(clippy::disallowed_types, reason = "internal DFS coloring scratch state, never rendered as output")]
319	fn detect_cycle(deps: &StepDependencies) -> Option<String> {
320	    #[derive(Clone, Copy, PartialEq)]
321	    enum Color {
322	        White,
323	        Gray,
324	        Black,
325	    }
326	
327	    fn visit<'a>(node: &'a str, deps: &'a StepDependencies, color: &mut HashMap<&'a str, Color>) -> Option<String> {
328	        color.insert(node, Color::Gray);
329	        if let Some(prereqs) = deps.edges.get(node) {
330	            for prereq in prereqs {
331	                let p = prereq.as_str();
332	                match color.get(p).copied() {
333	                    Some(Color::Gray) => return Some(p.to_string()),
334	                    Some(Color::White) | None => {
335	                        if color.get(p).copied() == Some(Color::White) {
336	                            if let Some(found) = visit(p, deps, color) {
337	                                return Some(found);
338	                            }
339	                        }
340	                    }
341	                    Some(Color::Black) => {}
342	                }
343	            }
344	        }
345	        color.insert(node, Color::Black);
346	        None
347	    }
348	
349	    let mut color: HashMap<&str, Color> = deps.ids.iter().map(|id| (id.as_str(), Color::White)).collect();
350	    for id in &deps.ids {
351	        if color.get(id.as_str()).copied() == Some(Color::White) {
352	            if let Some(found) = visit(id.as_str(), deps, &mut color) {
353	                return Some(found);
354	            }
355	        }
356	    }
357	    None
358	}
