366	/// The circuit breaker's current phase.
367	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
368	pub enum BreakerPhase {
369	    /// Calls are attempted normally.
370	    Closed,
371	    /// Calls are short-circuited without invoking the step.
372	    Open,
373	    /// A single probe call is allowed to test recovery.
374	    HalfOpen,
