377	/// A circuit breaker composing michi-resilience's retry math with
378	/// tokio-clock-based async waiting, per-attempt timeout, and
379	/// consecutive-failure circuit-opening. Internal state is held in
380	/// lock-free atomics so [`CircuitBreaker::phase`] stays synchronous.
381	pub struct CircuitBreaker {
382	    retry_config: michi_resilience::RetryConfig,
383	    step_timeout: Duration,
384	    failure_threshold: u32,
385	    open_duration: Duration,
386	    phase: AtomicU8,
387	    opened_at_ms: AtomicU64,
388	    consecutive_failures: AtomicU32,
389	    half_open_claimed: std::sync::atomic::AtomicBool,
390	    epoch: tokio::time::Instant,
391	}
392	
393	impl CircuitBreaker {
394	    /// Infallible, normalizing constructor. `failure_threshold == 0` is
395	    /// floored to 1; `step_timeout`/`open_duration` of `Duration::ZERO` are
396	    /// each independently floored to `Duration::from_millis(1)`.
397	    pub fn new(
398	        retry_config: michi_resilience::RetryConfig,
399	        step_timeout: Duration,
400	        failure_threshold: u32,
401	        open_duration: Duration,
402	    ) -> Self {
403	        let step_timeout = if step_timeout.is_zero() { Duration::from_millis(1) } else { step_timeout };
404	        let open_duration = if open_duration.is_zero() { Duration::from_millis(1) } else { open_duration };
405	        let failure_threshold = if failure_threshold == 0 { 1 } else { failure_threshold };
406	        Self {
407	            retry_config,
408	            step_timeout,
409	            failure_threshold,
410	            open_duration,
411	            phase: AtomicU8::new(PHASE_CLOSED),
412	            opened_at_ms: AtomicU64::new(0),
413	            consecutive_failures: AtomicU32::new(0),
414	            half_open_claimed: std::sync::atomic::AtomicBool::new(false),
415	            epoch: tokio::time::Instant::now(),
416	        }
417	    }
418	
419	    /// Current phase. Open is derived dynamically: once at least
420	    /// `open_duration` of tokio virtual time has elapsed since the breaker
421	    /// most recently opened, this reports `HalfOpen` even though the stored
422	    /// atomic still holds `PHASE_OPEN`.
423	    pub fn phase(&self) -> BreakerPhase {
424	        let raw = self.phase.load(Ordering::SeqCst);
425	        if raw == PHASE_OPEN {
426	            let opened_at_ms = self.opened_at_ms.load(Ordering::SeqCst);
427	            let elapsed_ms = u64::try_from(self.epoch.elapsed().as_millis()).unwrap_or(u64::MAX);
428	            let open_duration_ms = u64::try_from(self.open_duration.as_millis()).unwrap_or(u64::MAX);
429	            if elapsed_ms.saturating_sub(opened_at_ms) >= open_duration_ms {
430	                return BreakerPhase::HalfOpen;
431	            }
432	            return BreakerPhase::Open;
433	        }
434	        match raw {
435	            PHASE_HALF_OPEN => BreakerPhase::HalfOpen,
436	            _ => BreakerPhase::Closed,
437	        }
438	    }
439	}
