441	impl CircuitBreaker {
442	    fn record_failure(&self) {
443	        let count = self.consecutive_failures.fetch_add(1, Ordering::SeqCst) + 1;
444	        if count >= self.failure_threshold {
445	            self.open_circuit();
446	        }
447	    }
448	
449	    fn record_success(&self) {
450	        self.consecutive_failures.store(0, Ordering::SeqCst);
451	    }
452	
453	    fn open_circuit(&self) {
454	        let elapsed_ms = u64::try_from(self.epoch.elapsed().as_millis()).unwrap_or(u64::MAX);
455	        self.opened_at_ms.store(elapsed_ms, Ordering::SeqCst);
456	        self.phase.store(PHASE_OPEN, Ordering::SeqCst);
457	    }
458	}
