470	impl CircuitBreaker {
471	    /// Executes `step`, with behavior depending on [`CircuitBreaker::phase`].
472	    ///
473	    /// While `Open`, returns `Err(ExecutionError::CircuitOpen { retry_after_ms })`
474	    /// immediately without invoking `step` at all, where `retry_after_ms` is
475	    /// the time remaining until `open_duration` has elapsed since the
476	    /// breaker most recently opened.
477	    ///
478	    /// While `Closed`, retries retryable failures per `retry_config` with
479	    /// `next_retry_delay`'s backoff, threading `ExecutionError::Http`'s
480	    /// `retry_after` or `ExecutionError::CircuitOpen`'s `retry_after_ms`
481	    /// through when present -- including when either is wrapped inside
482	    /// `ExecutionError::StepFailed`'s `source`, which is unwrapped
483	    /// recursively. Returns immediately on success or
484	    /// on a non-retryable error, and returns the last error once
485	    /// `next_retry_delay` reports exhaustion. On success, resets the
486	    /// consecutive-failure counter; on a call-level failure (after retries
487	    /// are exhausted or the error is non-retryable), increments the counter
488	    /// once and opens the circuit at `failure_threshold`.
489	    ///
490	    /// While `HalfOpen`, runs `step` exactly once with no retries: success
491	    /// closes the circuit and resets the counter, and any failure reopens
492	    /// the circuit unconditionally, bypassing `failure_threshold`.
493	    pub async fn call(&self, step: &dyn Step, jitter_seed: f64) -> Result<(), ExecutionError> {
494	        let phase = self.phase();
495	        if phase == BreakerPhase::Open {
496	            let opened_at_ms = self.opened_at_ms.load(Ordering::SeqCst);
497	            let elapsed_ms = u64::try_from(self.epoch.elapsed().as_millis()).unwrap_or(u64::MAX);
498	            let open_duration_ms = u64::try_from(self.open_duration.as_millis()).unwrap_or(u64::MAX);
499	            let since_opened_ms = elapsed_ms.saturating_sub(opened_at_ms);
500	            let retry_after_ms = open_duration_ms.saturating_sub(since_opened_ms);
501	            return Err(ExecutionError::CircuitOpen { retry_after_ms });
502	        }
503	        if phase == BreakerPhase::HalfOpen {
504	            if self.half_open_claimed.compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst).is_err() {
505	                let open_duration_ms = u64::try_from(self.open_duration.as_millis()).unwrap_or(u64::MAX);
506	                return Err(ExecutionError::CircuitOpen { retry_after_ms: open_duration_ms });
507	            }
508	            let _gate_guard = HalfOpenGuard { claimed: &self.half_open_claimed };
509	            let attempt_result = match tokio::time::timeout(self.step_timeout, step.run(0)).await {
510	                Ok(result) => result,
511	                Err(_) => Err(ExecutionError::Timeout {
512	                    elapsed_ms: u64::try_from(self.step_timeout.as_millis()).unwrap_or(u64::MAX),
513	                }),
514	            };
515	            return match attempt_result {
516	                Ok(()) => {
517	                    self.phase.store(PHASE_CLOSED, Ordering::SeqCst);
518	                    self.record_success();
519	                    Ok(())
520	                }
521	                Err(err) => {
522	                    self.open_circuit();
523	                    Err(err)
524	                }
525	            };
526	        }
527	        let mut attempt = 0u32;
528	        loop {
529	            let attempt_result = match tokio::time::timeout(self.step_timeout, step.run(attempt)).await {
530	                Ok(result) => result,
531	                Err(_) => Err(ExecutionError::Timeout {
532	                    elapsed_ms: u64::try_from(self.step_timeout.as_millis()).unwrap_or(u64::MAX),
533	                }),
534	            };
535	            match attempt_result {
536	                Ok(()) => {
537	                    self.record_success();
538	                    return Ok(());
539	                }
540	                Err(err) => {
541	                    if !err.is_retryable() {
542	                        self.record_failure();
543	                        return Err(err);
544	                    }
545	                    let retry_after = retry_after_for(&err);
546	                    match michi_resilience::next_retry_delay(&self.retry_config, attempt, jitter_seed, retry_after) {
547	                        Some(delay) => {
548	                            tokio::time::sleep(delay).await;
549	                            attempt += 1;
550	                        }
551	                        None => {
552	                            self.record_failure();
553	                            return Err(err);
554	                        }
555	                    }
556	                }
557	            }
558	        }
559	    }
560	}
