562	/// Runs the steps of `pipeline` sequentially in declaration order through
563	/// `breaker`, writing each step's real outcome into `PipelineStep.status`.
564	pub async fn execute_pipeline(
565	    pipeline: &mut michi_core::pipeline::Pipeline,
566	    runners: Vec<Box<dyn Step>>,
567	    breaker: &CircuitBreaker,
568	    jitter_seed: f64,
569	    cancellation: &CancellationToken,
570	) -> Result<(), ExecutionError> {
571	    if runners.len() != pipeline.steps.len() {
572	        return Err(ExecutionError::StepCountMismatch { expected: pipeline.steps.len(), got: runners.len() });
573	    }
574	
575	    if cancellation.is_cancelled() {
576	        for step in pipeline.steps.iter_mut() {
577	            step.status = michi_core::pipeline::StepStatus::Skipped;
578	        }
579	        return Err(ExecutionError::Cancelled);
580	    }
581	
582	    for (idx, runner) in runners.iter().enumerate() {
583	        if idx > 0 && cancellation.is_cancelled() {
584	            for step in pipeline.steps[idx..].iter_mut() {
585	                step.status = michi_core::pipeline::StepStatus::Skipped;
586	            }
587	            return Err(ExecutionError::Cancelled);
588	        }
589	        let outcome = breaker.call(runner.as_ref(), jitter_seed).await;
590	        let step = &mut pipeline.steps[idx];
591	        match outcome {
592	            Ok(()) => {
593	                step.status = michi_core::pipeline::StepStatus::Completed;
594	            }
595	            Err(err) => {
596	                step.status = michi_core::pipeline::StepStatus::Failed;
597	                return Err(ExecutionError::StepFailed {
598	                    step_id: step.id.clone(),
599	                    step_name: step.name.clone(),
600	                    source: Box::new(err),
601	                });
602	            }
603	        }
604	    }
605	    Ok(())
606	}
