617	fn spawn_ready_steps(
618	    state: &mut [StepRunState],
619	    remaining_prereqs: &[usize],
620	    runners: &[std::sync::Arc<dyn Step>],
621	    breaker: &std::sync::Arc<CircuitBreaker>,
622	    jitter_seed: f64,
623	    join_set: &mut tokio::task::JoinSet<(usize, Result<(), ExecutionError>)>,
624	) {
625	    for i in 0..state.len() {
626	        if state[i] == StepRunState::Pending && remaining_prereqs[i] == 0 {
627	            state[i] = StepRunState::Running;
628	            let runner = std::sync::Arc::clone(&runners[i]);
629	            let breaker = std::sync::Arc::clone(breaker);
630	            join_set.spawn(async move {
631	                let result = breaker.call(runner.as_ref(), jitter_seed).await;
632	                (i, result)
633	            });
634	        }
635	    }
636	}
