638	fn propagate_skip(idx: usize, state: &mut [StepRunState], dependents_of: &[Vec<usize>]) {
639	    let mut stack = vec![idx];
640	    while let Some(i) = stack.pop() {
641	        for &d in &dependents_of[i] {
642	            if state[d] == StepRunState::Pending {
643	                state[d] = StepRunState::Skipped;
644	                stack.push(d);
645	            }
646	        }
647	    }
648	}
