650	/// Executes `pipeline.steps` concurrently, honoring the dependency edges in
651	/// `deps`. Steps with no unmet prerequisite run as soon as they become
652	/// eligible, polled concurrently via an internal `JoinSet`; a step only
653	/// starts once every step it depends on has reached a terminal status.
654	///
655	/// Every acceptance check runs in a fixed order before any step is
656	/// attempted: step-count mismatch, then a duplicate pipeline id, then an
657	/// id-set mismatch or unknown edge endpoint, then a cyclic dependency
658	/// (including a 1-node self-dependency).
659	///
660	/// On completion, each `PipelineStep.status` is written to `Completed`,
661	/// `Failed` (including a circuit-open short-circuit that never invokes
662	/// `Step::run`), or `Skipped` (every transitive dependent of a failed
663	/// step). The function returns `Ok(())` only if every step completed; on
664	/// any failure it returns `Err(ExecutionError::StepFailed)` identifying
665	/// one of the (possibly several) steps that failed, while every unrelated
666	/// in-flight step still runs to its own real terminal status rather than
667	/// being abandoned.
668	///
669	/// `breaker` is `Arc<CircuitBreaker>` rather than a plain reference,
670	/// unlike the unmodified, strictly sequential [`execute_pipeline`]: each
671	/// spawned step's task must independently hold a handle to the shared
672	/// breaker across the `JoinSet`'s `Send + 'static` boundary, which a
673	/// borrowed reference cannot satisfy.
674	pub async fn execute_pipeline_parallel(
675	    pipeline: &mut michi_core::pipeline::Pipeline,
676	    deps: &StepDependencies,
677	    runners: Vec<Box<dyn Step>>,
678	    breaker: std::sync::Arc<CircuitBreaker>,
679	    jitter_seed: f64,
680	    cancellation: &CancellationToken,
681	) -> Result<(), ExecutionError> {
682	    if runners.len() != pipeline.steps.len() {
683	        return Err(ExecutionError::StepCountMismatch { expected: pipeline.steps.len(), got: runners.len() });
684	    }
685	
686	    let mut seen_ids: HashSet<&str> = HashSet::new();
687	    let mut dup_ids: HashSet<&str> = HashSet::new();
688	    for step in &pipeline.steps {
689	        if !seen_ids.insert(step.id.as_str()) {
690	            dup_ids.insert(step.id.as_str());
691	        }
692	    }
693	    if !dup_ids.is_empty() {
694	        for (dependent, prereqs) in &deps.edges {
695	            if dup_ids.contains(dependent.as_str()) {
696	                return Err(ExecutionError::DuplicateStepId { step_id: dependent.clone() });
697	            }
698	            for p in prereqs {
699	                if dup_ids.contains(p.as_str()) {
700	                    return Err(ExecutionError::DuplicateStepId { step_id: p.clone() });
701	                }
702	            }
703	        }
704	    }
705	
706	    let pipeline_ids: HashSet<&str> = pipeline.steps.iter().map(|s| s.id.as_str()).collect();
707	    let graph_ids: HashSet<&str> = deps.ids.iter().map(|s| s.as_str()).collect();
708	    for id in &pipeline_ids {
709	        if !graph_ids.contains(id) {
710	            return Err(ExecutionError::UnknownStepId { step_id: (*id).to_string() });
711	        }
712	    }
713	    for id in &graph_ids {
714	        if !pipeline_ids.contains(id) {
715	            return Err(ExecutionError::UnknownStepId { step_id: (*id).to_string() });
716	        }
717	    }
718	    for (dependent, prereqs) in &deps.edges {
719	        if !pipeline_ids.contains(dependent.as_str()) {
720	            return Err(ExecutionError::UnknownStepId { step_id: dependent.clone() });
721	        }
722	        for p in prereqs {
723	            if !pipeline_ids.contains(p.as_str()) {
724	                return Err(ExecutionError::UnknownStepId { step_id: p.clone() });
725	            }
726	        }
727	    }
728	
729	    if let Some(step_id) = detect_cycle(deps) {
730	        return Err(ExecutionError::CyclicDependency { step_id });
731	    }
732	
733	    let id_at: Vec<String> = pipeline.steps.iter().map(|s| s.id.clone()).collect();
734	    #[allow(clippy::disallowed_types, reason = "internal id-to-index lookup, never rendered as output")]
735	    let index_of: HashMap<&str, usize> = id_at.iter().enumerate().map(|(i, id)| (id.as_str(), i)).collect();
736	
737	    let mut prereqs_of: Vec<Vec<usize>> = vec![Vec::new(); id_at.len()];
738	    let mut dependents_of: Vec<Vec<usize>> = vec![Vec::new(); id_at.len()];
739	    for (dependent, prereqs) in &deps.edges {
740	        let d_idx = index_of[dependent.as_str()];
741	        for p in prereqs {
742	            let p_idx = index_of[p.as_str()];
743	            prereqs_of[d_idx].push(p_idx);
744	            dependents_of[p_idx].push(d_idx);
745	        }
746	    }
747	
748	    let mut state: Vec<StepRunState> = vec![StepRunState::Pending; id_at.len()];
749	    let mut remaining_prereqs: Vec<usize> = prereqs_of.iter().map(Vec::len).collect();
750	    let runners: Vec<std::sync::Arc<dyn Step>> = runners.into_iter().map(std::sync::Arc::from).collect();
751	
752	    let mut join_set: tokio::task::JoinSet<(usize, Result<(), ExecutionError>)> = tokio::task::JoinSet::new();
753	    let mut first_failure: Option<(usize, ExecutionError)> = None;
754	    let mut cancelled = false;
755	
756	    if cancellation.is_cancelled() {
757	        cancelled = true;
758	        for st in state.iter_mut() {
759	            if *st == StepRunState::Pending {
760	                *st = StepRunState::Skipped;
761	            }
762	        }
763	    } else {
764	        spawn_ready_steps(&mut state, &remaining_prereqs, &runners, &breaker, jitter_seed, &mut join_set);
765	    }
766	
767	    while let Some(joined) = join_set.join_next().await {
768	        let (i, result) = match joined {
769	            Ok(pair) => pair,
770	            Err(join_err) => std::panic::resume_unwind(join_err.into_panic()),
771	        };
772	        match result {
773	            Ok(()) => {
774	                state[i] = StepRunState::Completed;
775	                pipeline.steps[i].status = michi_core::pipeline::StepStatus::Completed;
776	                for &d in &dependents_of[i] {
777	                    if state[d] == StepRunState::Pending {
778	                        remaining_prereqs[d] = remaining_prereqs[d].saturating_sub(1);
779	                    }
780	                }
781	            }
782	            Err(err) => {
783	                state[i] = StepRunState::Failed;
784	                pipeline.steps[i].status = michi_core::pipeline::StepStatus::Failed;
785	                if first_failure.is_none() {
786	                    first_failure = Some((i, err));
787	                }
788	                propagate_skip(i, &mut state, &dependents_of);
789	            }
790	        }
791	        if cancellation.is_cancelled() && state.contains(&StepRunState::Pending) {
792	            cancelled = true;
793	            for st in state.iter_mut() {
794	                if *st == StepRunState::Pending {
795	                    *st = StepRunState::Skipped;
796	                }
797	            }
798	        } else {
799	            spawn_ready_steps(&mut state, &remaining_prereqs, &runners, &breaker, jitter_seed, &mut join_set);
800	        }
801	    }
802	
803	    for (i, st) in state.iter().enumerate() {
804	        if *st == StepRunState::Skipped {
805	            pipeline.steps[i].status = michi_core::pipeline::StepStatus::Skipped;
806	        }
807	    }
808	
809	    match first_failure {
810	        Some((i, err)) => Err(ExecutionError::StepFailed {
811	            step_id: pipeline.steps[i].id.clone(),
812	            step_name: pipeline.steps[i].name.clone(),
813	            source: Box::new(err),
814	        }),
815	        None if cancelled => Err(ExecutionError::Cancelled),
816	        None => Ok(()),
817	    }
818	}
